arguments.content:
import { Chess } from './src/chess'

for (const file of 'abcdefgh') {
  const square = file + '1'
  const chess = new Chess()
  chess.put({ type: 'p', color: 'b' }, square as never)
  try {
    const sans = chess.moves({ square: square as never })
    const all = chess.moves().length
    console.log(`black pawn ${square}: sans=${JSON.stringify(sans)} all=${all}`)
  } catch (e) {
    console.log(`black pawn ${square}: THREW ${e instanceof Error ? e.message : e}`)
  }
}

