import { Chess } from './src/chess'

const chess = new Chess()
chess.put({ type: 'p', color: 'b' }, 'a1')

const pseudo = (chess as unknown as { _moves: (a?: unknown) => unknown[] })._moves(
  { square: 'a1', legal: false },
) as { from: number; to: number }[]
console.log('pseudo-moves for a1 pawn:', JSON.stringify(pseudo))

// also: does _pieceKey(128) blow up?
const pk = (chess as unknown as { _pieceKey: (i: number) => bigint })._pieceKey
console.log('board[128] after put:', (chess as unknown as { _board: unknown[] })._board[128])

