import { Chess } from './src/chess'

for (const file of 'abcdefgh') {
  const square = (file + '1') as `a${string}`
  const chess = new Chess(
    'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR b KQkq - 0 1',
