    const sans = chess.moves({ square })
    const all = chess.moves().length
    console.log(`black pawn ${square}: sans=${JSON.stringify(sans)} all=${all}`)
  } catch (e) {
    console.log(`black pawn ${square}: THREW ${e instanceof Error ? e.message : e}`)
  }
}

